@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    if (target == null || resultMap == null) return;
    try {
        // Create two partitions of the bipartite graph
        int leftSize = 3;
        int rightSize = 3;
        java.util.List<V> left = new java.util.ArrayList<>();
        java.util.List<V> right = new java.util.ArrayList<>();

        // Add left partition vertices
        for (int i = 0; i < leftSize; i++) {
            @SuppressWarnings("unchecked")
            V v = (V) Integer.valueOf(i);
            target.addVertex(v);
            left.add(v);
            resultMap.put("left" + i, v);
        }

        // Add right partition vertices
        for (int i = 0; i < rightSize; i++) {
            @SuppressWarnings("unchecked")
            V v = (V) Integer.valueOf(leftSize + i);
            target.addVertex(v);
            right.add(v);
            resultMap.put("right" + i, v);
        }

        // Connect every vertex in left to every vertex in right
        for (V lv : left) {
            for (V rv : right) {
                target.addEdge(lv, rv);
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to generate complete bipartite graph", e);
    }
