private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("start node must not be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("stop node must not be null");
    }

    // Create a circulator starting at the given node and direction
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // If the start node is already the stop node, return immediately
    if (start.equals(stop)) {
        return circ;
    }

    // Iterate around the outer face until we either find a node that satisfies the predicate
    // or we reach the stop node.  We also guard against infinite loops by breaking if we
    // return to the start node without having found the stop node.
    while (!circ.current().equals(stop)) {
        if (predicate.test(circ.current())) {
            return circ;
        }
        circ.next();
        if (circ.current().equals(start)) {
            // We have looped back to the start without encountering the stop node.
            // Break to avoid an infinite loop.
            break;
        }
    }

    // If we exited the loop without finding a matching node, move the circulator
    // to the stop node (if reachable).  If the stop node is not reachable, the
    // circulator will remain at the last node visited.
    while (!circ.current().equals(stop)) {
        circ.next();
        if (circ.current().equals(start)) {
            // Stop node not reachable; break out.
            break;
        }
    }

    return circ;
}<|return|>

