private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null) {
        return result;
    }
    TreeSet<Integer> sorted = new TreeSet<>();
    for (K k : keys) {
        if (k == null) {
            continue;
        }
        try {
            sorted.add((Integer) k);
        } catch (ClassCastException e) {
            // ignore non-integer keys
        }
    }
    for (K k : keys) {
        if (k == null) {
            result.add(null);
            continue;
        }
        try {
            Integer key = (Integer) k;
            Integer lower = sorted.lower(key);
            result.add(lower);
        } catch (ClassCastException e) {
            result.add(null);
        }
    }
    return result;
